const D = { energy: .6, scale: 1, density: .55, speed: 1, haze: .6, bob: .5, hue: 34, x: .5, y: .52, style: 'dusk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A sky archipelago: chunks of land torn loose and hung in the air, their broken rock
// undersides trailing thin ribbon waterfalls into the void, cloud strata sliding between them.
// Depth is parallax + atmosphere: near islands are huge, warm and drift fast; far ones shrink,
// blue out and creep. Each island floats on its own incommensurate rate so the sky never repeats. ----
const u = Math.min(width, height);
const hu = h => ((h % 360) + 360) % 360;
const fr = i => { let h = (Math.imul(i|0, 374761393) + Math.imul(P.seed|0, 2246822519) + 3266489917) | 0; h = Math.imul(h ^ (h >>> 15), 2246822519); return ((h ^ (h >>> 13)) >>> 0) / 4294967295; };
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const ho = P.hue - 34;

const STY = {
  // golden-hour: warm lit tops, cool violet shadow undersides, hazy amber horizon
  dusk:    { zen:[224,66,26], hor:[34,60,74], cloud:[30,26,84], rock:[262,32,20], rockLit:[30,52,60], grass:[96,54,42], grassLit:[64,60,66], fall:[38,20,98], ink:0 },
  // storm: slate sky, near-black islands, pale cold waterfalls
  storm:   { zen:[218,50,14], hor:[210,26,42], cloud:[212,20,54], rock:[216,34,12], rockLit:[210,20,34], grass:[150,30,26], grassLit:[140,30,40], fall:[200,10,92], ink:0 },
  // pastel dawn: pink & lavender, soft and high-key but still legible
  dawn:    { zen:[236,44,40], hor:[336,34,86], cloud:[320,20,92], rock:[276,26,34], rockLit:[338,30,72], grass:[110,34,54], grassLit:[80,40,72], fall:[320,14,99], ink:0 },
  // verdant midday: lush greens, bright teal void, storybook clarity
  verdant: { zen:[204,68,48], hor:[186,40,82], cloud:[190,16,94], rock:[28,44,30], rockLit:[36,50,58], grass:[118,66,48], grassLit:[92,70,74], fall:[190,18,99], ink:0 },
  // ABSTRACTED sumi: monochrome wash, islands as ink masses, waterfalls as bare paper
  ink:     { zen:[210,14,30], hor:[36,10,72], cloud:[30,8,80], rock:[220,10,12], rockLit:[34,12,40], grass:[150,12,26], grassLit:[120,14,44], fall:[40,4,98], ink:1 }
};
const st = STY[P.style] || STY.dusk;
const zen = [hu(st.zen[0]+ho), st.zen[1], st.zen[2]];
const en = Math.max(0, Math.min(1, P.energy));
const NP = 4;                                      // depth planes, 0 = farthest
const hy = height * P.y;                            // atmospheric horizon
const key = [width, height, P.style, P.seed, Math.round(P.hue), P.scale.toFixed(2), P.density.toFixed(2)].join('|');

if (!S.sky || S.key !== key) {
  if (S.sky) { S.sky.remove(); if (S.isl) S.isl.forEach(o => o.g.remove()); }
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke(); return g; };

  // sky gradient: deep zenith to bright hazy horizon
  S.sky = mk(W, H);
  const g = S.sky; const hor = [hu(st.hor[0]+ho), st.hor[1], st.hor[2]];
  for (let yy = 0; yy < H; yy++) { const f = Math.pow(Math.min(1, yy/H), .9); const c = L3(zen, hor, Math.min(1, f*1.15)); g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1); }

  // build islands across depth planes
  S.isl = [];
  const rock = [hu(st.rock[0]+ho), st.rock[1], st.rock[2]], rockLit = [hu(st.rockLit[0]+ho), st.rockLit[1], st.rockLit[2]];
  const grass = [hu(st.grass[0]+ho), st.grass[1], st.grass[2]], grassLit = [hu(st.grassLit[0]+ho), st.grassLit[1], st.grassLit[2]];
  let id = 0;
  for (let p = 0; p < NP; p++) {
    const f = (p + 1) / NP;                          // nearness
    const haze = (1 - f) * .82;
    const nI = Math.max(1, Math.round((1.6 + f * 2.4) * (.6 + P.density)));
    for (let s = 0; s < nI; s++) {
      const iw = Math.max(8, Math.ceil(u * (.10 + f * .34) * P.scale * (.6 + fr(id*9+1)*.9)));
      const ih = Math.max(8, Math.ceil(iw * (.7 + fr(id*9+2)*.5)));
      const q = mk(iw, ih);
