      const rc = L3(rock, [hu(st.hor[0]+ho), st.hor[1], st.hor[2]], haze);
      const rl = L3(rockLit, [hu(st.hor[0]+ho), st.hor[1], st.hor[2]], haze*.7);
      q.fill(rc[0], rc[1], rc[2], st.ink?100:96);
      q.beginShape();
      q.vertex(iw*.04, capY);
      const tip = ih*(.86 + fr(id*9+3)*.12), tipx = cx + (fr(id*9+4)-.5)*iw*.3;
      const nv = 7;
      for (let v = 0; v <= nv; v++) { const t0 = v/nv; const x = iw*.04 + t0*iw*.92; const depth = Math.sin(t0*Math.PI)*(tip-capY); const jag = (fr(id*30+v)-.5)*ih*.10; q.vertex(x, capY + depth + jag); }
      q.endShape(q.CLOSE);
      // strata bands on the rock
