      // grass cap with lit crown
      const gc = L3(grass, [hu(st.hor[0]+ho), st.hor[1], st.hor[2]], haze);
      const gl = L3(grassLit, [hu(st.hor[0]+ho), st.hor[1], st.hor[2]], haze*.6);
      q.fill(gc[0], gc[1], gc[2], 100); q.ellipse(cx, capY, iw*.96, capY*1.7);
      q.fill(gl[0], gl[1], Math.min(100, gl[2]+8), 90); q.ellipse(cx - iw*.06, capY*.7, iw*.7, capY*1.1);
      // tree tufts / rocks on top for texture
      const nt = Math.round(2 + fr(id*9+5)*4);
      for (let t = 0; t < nt; t++) { const tx = iw*.2 + fr(id*40+t)*iw*.6; const th = ih*(.06+fr(id*40+t+1)*.10); q.fill(gc[0], gc[1]*1.1, gc[2]*.5, 90); q.triangle(tx-th*.4, capY*.6, tx+th*.4, capY*.6, tx, capY*.6-th); }
      if (st.ink) for (let i = 0; i < 90; i++) { q.fill(30, 6, fr(i*7+id)>.5?26:6, 4); q.rect(fr(i*3+id)*iw, fr(i*3+id+1)*ih, u*.003, u*.003); }
      // waterfall origin: relative x along the underside where a ribbon falls
      const fallRx = .3 + fr(id*9+6)*.4;
      S.isl.push({ g: q, w: iw, h: ih, f: f, bx: (s + .5 + (fr(id*9+7)-.5)*.8)/nI, by: (fr(id*9+8)-.5)*.7*(1-f)+ (.5-f*.25), rate: u*(.0018)*Math.pow(f,1.3)*(.7+fr(id*9+9)*.6), rph: fr(id*11)*6.28, fx: fallRx, flen: (.5+fr(id*9+2)*.9)*(0.4+f), fw: iw });
      id++;
    }
  }
  S.isl.sort((a,b)=>a.f-b.f);                        // far first
  S.key = key;
}

// ---------------- draw ----------------
noStroke();
image(S.sky, 0, 0);

// cloud strata between the islands (a few soft bands drifting at incommensurate rates)
const cloudC = [hu(st.cloud[0]+ho), st.cloud[1], st.cloud[2]];
blendMode(st.ink? BLEND : ADD);
for (let b = 0; b < 4; b++) {
  const f = (b+1)/4; const cy = hy - u*.1 + b*u*.09 + Math.sin(K.t*(.01+b*.006))*u*.02;
  const drift = (K.t * (.4 + f*1.2) * P.speed * u*.004) % (width*1.4);
  for (let i = 0; i < 5; i++) { const cx = ((i*width*.3 - drift + fr(b*5+i)*width) % (width*1.4)) - width*.2; fill(cloudC[0], cloudC[1]*.7, cloudC[2], (2.5+3*P.haze)*(.4+f*.6)); ellipse(cx, cy + Math.sin(i+b)*u*.01, width*(.24+f*.18), u*(.05+f*.05)); }
}
blendMode(BLEND);

// islands, far -> near, each drifting on its own incommensurate rate + slow bob
const fallC = [hu(st.fall[0]+ho), st.fall[1], st.fall[2]];
for (let k = 0; k < S.isl.length; k++) {
  const o = S.isl[k];
  const dx = ((o.bx*width - K.t * o.rate * 26 * P.speed + Math.sin(K.t*(.05+o.f*.03)+o.rph)*u*.01) % (width*1.5) + width*1.5) % (width*1.5) - width*.25;
  const dy = o.by*height + Math.sin(K.t*(.09+o.f*.05)+o.rph)*u*.02*P.bob + Math.sin(K.t*(.031)+o.rph*2)*u*.012*P.bob;
