  blendMode(ADD);
  for (let s2 = 0; s2 < 3; s2++) {
    const sw = o.w*(.03 + s2*.02)*(1-.2*s2);
    for (let seg = 0; seg < 10; seg++) {
      const t0 = seg/10; const yy = foy + t0*flen; const wob = Math.sin((yy*.02) - K.t*(3+o.f*3) + s2)*sw*.5;
